mapper.update:
UPDATE project
SET owner_user_id = #{newOwnerUserId},
    updated_at = #{updatedAt}
WHERE id = #{projectId}
  AND owner_user_id = #{previousOwnerUserId}

UPDATE project
SET name = #{name},
    watermark_enabled = #{watermarkEnabled},
    default_watermark_position = #{defaultWatermarkPosition},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'active'
  AND owner_user_id = #{ownerUserId}

UPDATE project
SET status = 'archived',
    updated_at = #{updatedAt}
WHERE id = #{projectId}
  AND status = 'active'
  AND owner_user_id = #{ownerUserId}

mapper.delete:
DELETE user_message
FROM user_message
LEFT JOIN project_invite ON project_invite.id = user_message.invite_id
WHERE user_message.project_id = #{projectId}
   OR project_invite.project_id = #{projectId}

DELETE FROM project
WHERE id = #{projectId}
  AND status = 'archived'
  AND owner_user_id = #{ownerUserId}
